  'faq.daily_salary': '日工资如何计算？',
  'faq.daily_salary_answer':
    '用您含额外工资的年度税前工资除以365。CGPJ 指南计算补偿金时就是这样算的。',
  'faq.erte': '如果我在 ERTE 期间被解雇呢？',
  'faq.erte_answer':
    '补偿金应按 ERTE 之前的全额工资计算，而不是按您最近几张工资单的金额。如果是缩短工时，按缩短之前的工资（STS 678/2018, de 27 de junio）；如果合同被中止，按工作月份实际领取的工资（STS 638/2022, de 7 de julio）。本核查会请您填写这个工资，没有它就不给出金额。',
  'faq.fixed_term': '定期合同结束时有补偿金吗？',
  'faq.fixed_term_answer':
    '有，每年12天，按实际工作天数折算（art. 49.1.c ET）。如果合同在2011年或之前开始，是8天；2012年开始是9天；2013年是10天；2014年是11天（disposición transitoria 8.ª ET）。替岗合同和培训类合同没有补偿金，2001年三月4日之前签订的合同也没有（disposición transitoria 8.ª.2 ET）。',
  'faq.unknown_cause': '如果我不知道合同是如何结束的呢？',
  'faq.unknown_cause_answer':
    '请选择“不知道”。核查会检查与原因无关的项目：离职当月的工资、年假和额外工资。补偿金取决于原因，没有原因就不计算。原因写在解雇信和公司离职证明（certificado de empresa）上的“causa de la situación legal de desempleo”一栏。',
  'faq.deadlines': '离职结算少付的部分，我有多长时间可以主张？',
  'faq.deadlines_answer':
    '对于未付工资、年假、额外工资或定期合同到期补偿金等款项，期限为一年（art. 59.1 ET）。如果是解雇（客观原因、集体、不当或纪律解雇），对解雇提出异议的期限为20个工作日（art. 59.3 ET），对补偿金有异议的人通常也通过同一途径提出。期限很短，劳动法律师事务所、社会事务师（graduado social）事务所或工会可以告诉您适用于您情况的是哪一个。',
  'faq.null_dismissal': '什么情况下解雇可能无效？',
  'faq.null_dismissal_answer':
    '如果您在怀孕期间、休生育、收养、监护或寄养假期间或休完回来后的12个月内被解雇，或在享有或申请过照护假、缩短工时、工时调整或照护停薪留职时被解雇，或您是性别暴力或性暴力的受害者，解雇可能无效（nulo），除非解雇理由与该情况毫无关系（art. 55.5 ET）。在病假期间被解雇，如果理由是疾病，也可能无效（Ley 15/2022, arts. 2.1 y 26），不过法院目前的适用还不统一。如果您勾选了这种情况，核查会提醒您，但不会给出这种情况下的金额。对解雇提出异议的期限为20个工作日（art. 59.3 ET）。',
  'faq.late_interest': '如果公司还没有支付离职结算呢？',
  'faq.late_interest_answer':
    '属于工资的部分，从离职之日起按每年10 %计算延迟利息（art. 29.3 ET），即使金额存在争议也是如此（STS de 17 de junio de 2014, rcud 1315/2013）。核查按离职当月工资和额外工资的法定最低金额计算利息。补偿金不计这种利息；未休年假是否计息存疑，因此不计入。主张离职结算款项的期限为离职后一年（art. 59.1 y 59.2 ET）。',
  'faq.benefit': '如果我被解雇或合同到期，能领失业金吗？',
  'faq.benefit_answer':
    '任何解雇都属于法定失业状态（situación legal de desempleo），纪律解雇即使被认定为正当也是如此；定期合同到期，只要不是您自己终止的，也属于法定失业状态（arts. 267.1.a y 268.4 LGSS）。自己决定离职则不属于，但有例外，例如调岗异地或公司严重拖欠工资（art. 267 LGSS）。此外，还需要在过去6年中缴费360天（可以来自多份工作），并登记为求职者，以及满足其他条件（arts. 266 y 269.1 LGSS）。',
  'faq.benefit_amount': '我能领多少失业金？',
  'faq.benefit_amount_answer':
    '取决于过去180天的失业险缴费。前180天领取该基数的70 %，之后领取60 %（art. 270 LGSS）；2026年每月税前金额在560 €到1.575 €之间，视您需要抚养的子女而定（SEPE）。领取期限为120到720天，取决于过去6年的缴费（art. 269.1 LGSS）。离职结算核查会根据您的数据按全职估算。',
  'faq.not_agreed': '以“不同意”（no conforme）的方式签署离职结算是什么意思？',
  'faq.not_agreed_answer':
    '就是在签署时加上“已收到，但不同意”（recibí no conforme）或“不同意”（no conforme）。有些人在不认同某项金额时会这样做。法律还规定，您可以要求员工法定代表中的一人在场（art. 49.2 ET）。我们只是介绍这些信息，每种情况下怎么做，可以由劳动法律师事务所、社会事务师（graduado social）事务所或工会来评估。',
  'faq.not_checkable': '什么时候某一项会显示“无法核查”？',
  'faq.not_checkable_answer':
    '当缺少某个数据、没有它就没有可对比的法定金额时。辞职的提前通知期就是这样，它由您的集体协议规定；如果您选择了“不知道”，已休年假天数也是如此。年假和额外工资是会对比的。由于公司按天或按月计算，这里给出两种算法之间的范围，您的集体协议可能规定更高的数额。',
  'faq.data': '我的数据会被发送到别处吗？',
  'faq.data_answer':
    '您填写的内容不会。核查完全在您的浏览器中计算，不会保存。我们会统计您使用了哪些步骤，不使用 cookie，也不确认您的身份：您打开了哪些栏目、哪个字段未被接受、差额落在哪个区间。绝不包括您的金额和日期。详情请见隐私页面。',
  'final_pay.lead_documents':
    '按解雇、主动辞职或合同到期等情况，计算您的离职结算（finiquito）的法定最低金额，并与公司给出的金额对比。您可以填写数据，或上传离职结算单的照片。',
  'faq.pass': '4,99 €的通行证包括什么？',
  'faq.pass_answer':
    '通行证在7天内可用于任何核查，且只在您付款时使用的浏览器中有效：在此期间，您可以重做或修改核查，识别最多15份文件包，并重新下载报告和信函，无需再次付款。我们不会在任何地方保存您的核查，因此请在付款后尽快下载报告和信函。通行证只存在于该浏览器中：换一台设备、使用无痕窗口或清除浏览数据后，通行证就会丢失；“已经付过款？”也只能在您付款时使用的浏览器中找回。',
  'faq.documents': '我的文件会怎样处理？',
  'faq.documents_answer':
    '如果您上传文件（解雇信、离职结算单、工资单、公司离职证明或工作履历报告），文件会加密发送到 Amazon Web Services 位于西班牙的服务器，服务器再将其交给欧盟境内的一个 AI 模型（Anthropic 的 Claude，通过 Amazon Bedrock）。模型识别每一页是什么，只抄录表单需要的数据，不做任何计算。服务器和模型都不保存文件：文件在内存中处理后即被丢弃。上传之前我们会征求您的同意，因为工资单可能显示敏感数据。如果您不想上传任何文件，可以自己填写数据，这样就没有任何内容离开您的设备。',
  'not_found.title': '页面未找到 · eslojusto.es',
  'not_found.description':
    '这个地址没有对应 eslojusto.es 的任何页面。您可以从这里前往离职结算核查或首页。',
  'not_found.h1': '找不到这个页面',
  'not_found.lead': '可能是链接写错了，或者页面的地址已经变更。',
