  'rent_indices.example':
    '您的合同签订于2024年，按 IRAV 更新，每月租金为{renta}。{dia}合同又满一年，当天最新公布的 IRAV 是{mes}的：{irav}，公布于{publicado}。您的租金最多可以涨到{maximo}。',
  'rent_indices.example_later':
    '如果在{dia}满一年，在{norma}有效期间，无新约定时上限为2 %，如果 IRAV 更低则按 IRAV：最多{maximo}。此外，如果您的住房位于住房市场紧张地区，且这{renta}超过了参考指数系统在当地确定的价格上限，租金就不能上涨。',
  'rent_indices.check_title': '核查您的涨租',
  'rent_indices.check':
    '根据您的合同日期和每个月的指数，核查房东给您涨的租金是否超出法律允许的范围。',
  'rent_indices.check_link': '核查我的租房',
  'rent_indices.faq': '常见问题',
  'rent_indices.faq.what_is_irav': '什么是 IRAV？',
  'rent_indices.faq.what_is_irav_answer':
    '这是 INE 每月公布、用于限制住房租金年度涨幅的指数（disposición adicional 11.ª LAU）。它取 IPC、核心 IPC 以及一个使结果趋近2 %的平均值三者中的最低值。自2025年一月1日起作为上限使用。',
  'rent_indices.faq.which_month': '我的涨租按哪个月的指数计算？',
  'rent_indices.faq.which_month_answer':
    '按合同每满一年那天最新公布的指数计算，而不是那天所在月份的指数（art. 18.1 LAU）。如果您的合同在{dia}满一年，适用{mes}的 IRAV，公布于{publicado}。',
  'rent_indices.faq.irav_or_ipc': '我适用 IRAV 还是 IPC？',
  'rent_indices.faq.irav_or_ipc_answer':
    '取决于您的合同何时开始以及何时满一年。自2025年起，2023年五月26日起签订的合同，上限为 IRAV 和 IPC 中较低者；此前签订的合同，上限为 IPC。{decreto}',
  'rent_indices.faq.decree_live': '自{desde}起，{norma}规定所有合同都适用 IRAV（{estado}）。',
  'rent_indices.faq.decree_repealed':
    '{norma}曾规定所有合同都适用 IRAV（{periodo}），但已被众议院废止。',
  'rent_indices.faq.flash': 'IPC 预估值算数吗？',
  'rent_indices.faq.flash_answer':
    'INE 在每月月底给出 IPC 的估算，大约两周后公布最终值。法律说的是最新公布的指数，没有明确预估值是否算数，因此这里两者都列出。IRAV 没有预估值：它与 IPC 最终值一同公布。',
  'rent_indices.faq.no_clause': '如果合同中什么都没写，房东可以给我涨租吗？',
  'rent_indices.faq.no_clause_answer':
    '如果您的合同签订于2015年四月1日或之后，则不可以：没有更新条款，租金就不更新（art. 18.1 LAU）。如果条款规定租金会更新，但没写按哪个指数，则使用 IGC，但在规定适用 IRAV 的法令有效期间除外：{decretos}。对于2015年四月1日之前签订的合同，按1994年的文本或 Ley 4/2013 的文本，即使合同没有写明，法律也会按 IPC 更新租金。',
  'rent_indices.faq.no_clause_item': '{norma}（{periodo}，{estado}）',
  'rent_indices.faq.igc_negative': '为什么 IGC 会是负值？',
  'rent_indices.faq.igc_negative_answer':
    'INE 按其公式计算的结果原样公布 IGC，该公式将西班牙的价格与欧元区的价格进行比较。用它来调整价格时，Ley 2/2015 将其限定在0 %至2 %之间：如果为负值，调整幅度为0 %。',
  'rent_indices.dataset_name': '每月的 IRAV、IPC 和 IGC',
  'rent_indices.dataset_description':
    '自2024年十一月起每个月的住房租赁参考指数（Índice de Referencia de Arrendamientos de Vivienda，IRAV）、消费者价格指数（Índice de Precios de Consumo，IPC，预估值和最终值）和竞争力保障指数（Índice de Garantía de Competitividad，IGC）的年度变化率，附 INE 公布每个数字的日期。',
  'rental.documents.start_help':
    '您可以上传租房合同和其他租房文件，根据从中识别的内容填写数据，也可以自己填写。在进行任何计算之前，您会逐项确认每个数据。',
  'rental.documents.upload':
    '请上传您的租房合同，以及（如果有的话）涨租通知、收据、中介发票和押金退还凭证',
  'rental.documents.files_hint':
    '租房合同，以及（如果有的话）涨租通知、收据、中介发票或押金退还凭证，顺序不限。总共最多25张照片或 PDF 页面。照片和 PDF 页面会先在您的设备上转换为图片，再发送出去。',
  'rental.documents.consent':
    '我明确同意由 AI 识别这些文件并填写表单。我知道其中可能包含个人数据，例如姓名、DNI、地址或银行账号。文件在欧盟境内识别，且不会保存。',
  'rental.pass.title': '详细内容、报告和信函',
  'rental.pass.text':
    '支付4,99 €，即可查看每一项的逐步计算过程（逐月、逐年，附指数、适用的上限和法律来源），并下载 PDF 报告；如果您的核查中有相关数字，还可以下载关于押金和涨租的信函。这些文件在您的设备上生成。',
  'rental.pass.price':
    '4,99 €，含增值税（IVA）。一次性付款，无需注册账户，也不是订阅。通行证有效期7天，且只在本浏览器中有效，也可用于离职结算核查：在此期间，您可以重做或修改核查，识别最多15份文件包，并重新查看详细内容、下载报告和信函，无需再次付款。换一台设备、使用无痕窗口或清除浏览数据后，通行证就会丢失。',
  'rental.pass.paid_help':
    '如果您是在本浏览器中付的款，但看不到详细内容和下载，可以在这里找回您的通行证。只能在您付款时使用的浏览器中操作。',
  'rental.pass.waiver':
    '我现在就要查看详细内容和报告。我知道，由于这是即时交付的数字内容，我将失去撤回权（derecho de desistimiento，《消费者和用户权益保护总法》（Ley General para la Defensa de los Consumidores y Usuarios）art. 103.m）。',
  'rental.pass.download_deposit_letter': '下载押金信函（PDF）',
