  'rental.pass.letter_note':
    '这些信函是填入了您的数字的模板。它们下载到您的设备上，不会从这里发送：是否使用以及如何使用，由您自己决定。',
  'rental.letter.legend': '用于信函的个人信息（可选）',
  'rental.letter.landlord': '房东或公司的名称',
  'rental.letter.address': '房屋地址',
  'rental.letter.iban': '用于退还押金的账户（IBAN）',
  'rental.letter.iban_hint': '只出现在押金信函中。',
  'rental.letter.privacy': '这些信息只用于在您的设备上填写信函，不会发送，也不会保存。',
  'rental.title': '涨租和押金：核查您是否多付了钱',
  'rental.description':
    '逐项核查您租房的涨租、押金、各项费用或中介费是否超出法律允许的范围，并注明每一项所依据的法规。',
  'rental.h1': '核查您的租房是否公平',
  'rental.lead':
    '将您为住房租赁支付或已支付的费用与法律允许的范围进行对照：中介费、押金和担保、涨租、各项费用以及押金退还。',
  'rental.beta': '测试版',
