  'credit.pass.text':
    '支付4,99 €，即可下载 PDF 报告，其中包括计算 TAE 所用的付款表、每项费用使 TAE 增加的幅度以及提前还款的上限；如果您的核查中有相应数字，还可以下载关于提前还款补偿费的信函。这些文件在您的设备上生成。',
