  'client.household.calculation.night.inside':
    '对于住家人员，终止雇佣关系的决定不得在17:00至08:00之间执行，除非存在严重违反忠诚和信任义务的过错；本核查以通知您的时间为准。',
  'client.household.calculation.severance.figure':
    '补偿金：每服务一年12天工资。共{days}天，每天{daily}：{amount}。',
