  'client.household.calculation.unemployment.situation':
    'art. 11.2 规定的解约属于法定失业状态（situación legal de desempleo）：您可以申请失业金（paro）。',
  'client.household.calculation.unemployment.general_rules':
    '自2022年十月1日起，家政工须缴纳失业保险，并适用一般规则：在过去六年中缴费满360天（art. 266.b LGSS），且这些天数未用于领取其他失业金（art. 269.2 LGSS）；失业金为70 %，之后为60 %。本核查不计算失业金金额。',
  'household.title': '家政工：对照法律核查您的工资和解约',
