  'household.result.unemployment_text':
    '自 Real Decreto-ley 16/2022 起，家政工如果满足一般条件，可以领取失业金（paro），其中包括在之前六年中缴纳失业保险满360天（《社会保障总法》（Ley General de la Seguridad Social）arts. 266 y 269.1）。art. 11.2 规定的解约（desistimiento）与解雇（art. 267.1.a) 3.º）一样，属于法定失业状态（art. 267.1.a) 8.º），且自2022年十月1日起须缴纳失业保险（disposición transitoria 2.ª del Real Decreto-ley 16/2022）。',
