    '您最晚何时可以通知不再续保您的保单（póliza），变更通知是否按法律要求的提前时间送达；如果您是远程签订的，最晚何时可以撤回（desistir）。只涉及日期：不评估价格，也不评估保障范围。',
  'insurance.beta': 'Beta',
