  'insurance.documents.start_help':
    '您可以上传保单和续保通知，根据从中识别的内容填写数据，也可以自己填写。在进行任何核查之前，您需要确认每项数据。',
  'insurance.documents.upload': '请上传您的保单，以及（如果有的话）续保通知',
