  'insurance.guide.lead':
    '您最晚何时可以通知不续保，保险公司须提前多久通知您变更，以及您何时可以撤回，每个日期都注明所依据的条文。另外还介绍保险金额低于实际价值时会怎样。',
  'insurance.guide.sources': '来源',
